import{_ as a}from"./chunks/05-fabric.xjDD_k4p.js";import{_ as t,o,c as r,a2 as c}from"./chunks/framework.Dbgp30TS.js";const g=JSON.parse('{"title":"05 · Fabric：新渲染引擎的一天","description":"","frontmatter":{},"headers":[],"relativePath":"comics/05-fabric.md","filePath":"comics/05-fabric.md","lastUpdated":1794291790000}'),i={name:"comics/05-fabric.md"};function n(s,e,p,d,l,u){return o(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="_05-·-fabric-新渲染引擎的一天" tabindex="-1">05 · Fabric：新渲染引擎的一天 <a class="header-anchor" href="#_05-·-fabric-新渲染引擎的一天" aria-label="Permalink to &quot;05 · Fabric：新渲染引擎的一天&quot;">​</a></h1><p><img src="'+a+`" alt="Fabric 渲染流水线：commit → diff → mount"></p><h2 id="一、fabric-是谁" tabindex="-1">一、Fabric 是谁 <a class="header-anchor" href="#一、fabric-是谁" aria-label="Permalink to &quot;一、Fabric 是谁&quot;">​</a></h2><p>前面几章解决了&quot;怎么启动&quot;（02）和&quot;怎么调原生&quot;（03/04）。这一章回答最后一个大问题：<strong>React 算出来的界面，是怎么变成屏幕上的像素的？</strong></p><p>答案是一个纯 C++ 的渲染器，代号 Fabric。它的一天分六站：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>React 交稿 → 影子树 commit → Yoga 布局 → diff 拆单 → 指令清单 → 平台 mount</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="二、第一站-js-侧的接线员" tabindex="-1">二、第一站：JS 侧的接线员 <a class="header-anchor" href="#二、第一站-js-侧的接线员" aria-label="Permalink to &quot;二、第一站：JS 侧的接线员&quot;">​</a></h2><p>在 JS 世界里，Fabric 的前台接待叫 [ReactFabric.js](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/Libraries/Renderer/shims/ReactFabric.js)——它是 React 官方渲染器（react-reconciler）的 RN 适配层，通过 <code>BatchedBridge.registerCallableModule(&#39;ReactFabric&#39;)</code> 注册成&quot;原生可回调的模块&quot;，原生随时能反过来叫它。</p><p>真正的手柄在 [FabricUIManager.js:L112-L157](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/Libraries/ReactNative/FabricUIManager.js#L112-L157)：</p><blockquote><p>它用 Proxy 把 <code>global.nativeFabricUIManager</code>（C++ 注入的 JSI 对象）包一层，对外暴露 createNode/appendChild/completeRoot 等方法，并把它们<strong>缓存住</strong>——每次渲染不再反复跨语言找方法。</p></blockquote><p>还记得 02 章的 <code>createReactNativeComponentClass</code> 吗？它注册进 ReactNativeViewConfigRegistry 也是懒的：<strong>视图配置第一次渲染用到才登记</strong>。启动阶段一个不必要的手续都不办。</p><h2 id="三、第二站-影子树-shadowtree" tabindex="-1">三、第二站：影子树（ShadowTree） <a class="header-anchor" href="#三、第二站-影子树-shadowtree" aria-label="Permalink to &quot;三、第二站：影子树（ShadowTree）&quot;">​</a></h2><p>Fabric 的核心数据结构叫<strong>影子树</strong>——JS 树在 C++ 侧的&quot;影子分身&quot;。它不可变：每次更新不修改旧树，而是造一棵新树，像 git commit 一样带版本号（revision）。</p><p>React 处理完一次 setState，会调用 [UIManager.cpp:L191-L210](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactCommon/react/renderer/uimanager/UIManager.cpp#L191-L210) 的 <code>completeSurface</code> 把成果&quot;交稿&quot;给 Fabric。随后 [ShadowTree.cpp:L302-L333](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactCommon/react/renderer/mounting/ShadowTree.cpp#L302-L333) 执行 commit：</p><blockquote><p>commit 不是总一次成功——如果期间有别的线程也在 commit（并发渲染很常见），会发生版本冲突，Fabric 会<strong>带着最新版本重试</strong>，就像 git rebase 失败后再 rebase 一次。</p></blockquote><p>commit 成功后，[ShadowTree.cpp:L376-L417](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactCommon/react/renderer/mounting/ShadowTree.cpp#L376-L417) 会用新根替换旧根，并立刻调用 <code>layoutIfNeeded()</code>——这引出第三站。</p><h2 id="四、第三站-yoga-算布局" tabindex="-1">四、第三站：Yoga 算布局 <a class="header-anchor" href="#四、第三站-yoga-算布局" aria-label="Permalink to &quot;四、第三站：Yoga 算布局&quot;">​</a></h2><p>Flexbox 布局引擎 Yoga 就住在影子节点里。[YogaLayoutableShadowNode.cpp:L67-L90](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactCommon/react/renderer/components/view/YogaLayoutableShadowNode.cpp#L67-L90) 把样式交给 Yoga 节点，[L174-L190](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactCommon/react/renderer/components/view/YogaLayoutableShadowNode.cpp#L174-L190) 再把算好的 x/y/宽/高写回影子节点。</p><p>关键点：<strong>布局发生在 C++，而不是 JS</strong>。JS 只声明&quot;我想要什么样&quot;，量尺寸的活全程不出 C++ 半步——这是新架构流畅度的基础。</p><h2 id="五、第四五站-diff-拆单-生成指令" tabindex="-1">五、第四五站：diff 拆单，生成指令 <a class="header-anchor" href="#五、第四五站-diff-拆单-生成指令" aria-label="Permalink to &quot;五、第四五站：diff 拆单，生成指令&quot;">​</a></h2><p>新旧两棵树都齐了，现在需要知道&quot;到底哪里变了&quot;。这就是 [Differentiator.cpp:L122-L140](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactCommon/react/renderer/mounting/Differentiator.cpp#L122-L140) 的活：产出五种指令。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CREATE  造新视图        INSERT 挂子树</span></span>
<span class="line"><span>UPDATE  改属性          REMOVE 摘子树</span></span>
<span class="line"><span>DELETE  销毁</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>它不是傻乎乎地遍历整棵树——得益于&quot;平化节点&quot;优化（被 <code>collapsable</code> 折叠的纯布局节点），diff 在 [L195-L232](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactCommon/react/renderer/mounting/Differentiator.cpp#L195-L232) 会<strong>递归展开子树差异</strong>，一次 list 项插入也能精确到&quot;只动这一个节点&quot;。</p><p>指令清单交给 [MountingCoordinator.cpp:L71-L93](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactCommon/react/renderer/mounting/MountingCoordinator.cpp#L71-L93) 的 <code>calculateShadowViewMutations</code> 排好序。</p><h2 id="六、第六站-mount-上屏" tabindex="-1">六、第六站：mount 上屏 <a class="header-anchor" href="#六、第六站-mount-上屏" aria-label="Permalink to &quot;六、第六站：mount 上屏&quot;">​</a></h2><p>最后一步，[MountingCoordinator.cpp:L179-L188](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactCommon/react/renderer/mounting/MountingCoordinator.cpp#L179-L188)：</p><blockquote><p>mount 不做&quot;整树替换&quot;，而是<strong>基于 revision 增量推进</strong>：屏幕永远停在&quot;某个版本的指令播放完&quot;的连贯状态，旧树则被异步销毁——绝不在渲染线程上做析构。</p></blockquote><p>Android 端由 FabricUIManager 逐条执行指令，iOS 端由 RCTViewComponentView（下一站再见）逐条上屏。commit 收尾时还会回发 layout events（onLayout 就是从这来的，[ShadowTree.cpp:L464-L489](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactCommon/react/renderer/mounting/ShadowTree.cpp#L464-L489)）。</p><h2 id="七、这一章记住三件事" tabindex="-1">七、这一章记住三件事 <a class="header-anchor" href="#七、这一章记住三件事" aria-label="Permalink to &quot;七、这一章记住三件事&quot;">​</a></h2><ol><li><strong>影子树不可变 + 版本号</strong>：并发渲染不撕裂，diff 永远有确定的&quot;两棵树&quot;可比；</li><li><strong>布局在 C++</strong>：Yoga 内嵌在影子节点里，JS 不参与测量；</li><li><strong>指令化 mount</strong>：平台只听五种指令，跨端行为完全一致。</li></ol><h2 id="八、faq" tabindex="-1">八、FAQ <a class="header-anchor" href="#八、faq" aria-label="Permalink to &quot;八、FAQ&quot;">​</a></h2><p><strong>Q1：onLayout 是在哪一步触发的？</strong> commit 成功后由 ShadowTree 回发 layout events，经 event pipeline 回到 JS——所以它天然是异步批量的，别在 onLayout 里同步改状态指望同帧生效。</p><p><strong>Q2：为什么我的 View 上面找不到原生层级？</strong><code>collapsable</code> 的平化优化：纯布局用途的 View 会被 C++ 折叠掉，原生侧根本不存在。需要原生实体时设 <code>collapsable={false}</code>。</p><p><strong>Q3：旧 Paper 渲染器还在源码里吗？</strong> 在，作为兼容模式存在。但 bridgeless 默认走 Fabric，0.87 的新项目开箱即新渲染器。</p><hr><blockquote><p>下一章：<a href="./06-js-core">06 · JS 侧核心</a>——看不见的管家们：InitializeCore / Pressability / Animated / VirtualizedList。</p></blockquote>`,36)])])}const b=t(i,[["render",n]]);export{g as __pageData,b as default};
